.header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: #ECFDF5;
}

.burger {
  font-size: 24px;
  background: none;
  border: 0;
  cursor: pointer;
}

nav {
  width: 100%;              /* меню — отдельной строкой под логотипом */
}

.menu {
  display: none;            /* на телефоне меню спрятано */
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 12px 0 0;
  list-style: none;
}

.menu.open {
  display: flex;            /* класс open его показывает */
}

.burger {
  display: none;
}

@media (max-width: 768px) {
  /* логотип и ☰ в строку, меню переносится ниже */
  .header .container {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .burger {
    display: block;
  }

  /* меню — отдельной строкой на всю ширину */
  .header nav {
    order: 1;
    width: 100%;
  }

  .menu {
    display: none;
    flex-direction: column;
  }

  .menu.open {
    display: flex;
  }
}

.menu{display:none!important}

